1575:     fn queue_block_action(
1576:         &mut self,
1577:         sequence: i32,
1578:         position: play::BlockPosition,
1579:         place: bool,
1580:         writer: &mut impl Write,
1581:     ) -> io::Result<()> {
1582:         if !self.play_confirmed {
1583:             return Ok(());
1584:         }
1585:         if self.block_pending.is_some() {
1586:             self.correct_block(writer, position)?;
1587:             play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
1588:             return Ok(());
1589:         }
1590:         let Some(session) = self.backend_session else {
1591:             self.correct_block(writer, position)?;
1592:             play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
1593:             return Ok(());
1594:         };
1595:         let Some(state) = self.authoritative_block_state(position)? else {
1596:             play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
1597:             return Ok(());
1598:         };
1599:         let Ok(expected) = u32::try_from(state) else {
1600:             return Err(invalid_data("invalid block action coordinate/state"));
1601:         };
1602:         let (x, y, z) = (position.x, position.y, position.z);
1603:         let action_sequence = self
1604:             .block_sequence
1605:             .checked_add(1)
1606:             .ok_or_else(|| io::Error::other("block action sequence exhausted"))?;
1607:         match self
1608:             .backend
1609:             .block_action_submit(session, action_sequence, x, y, z, expected, place)
1610:         {
1611:             Ok(receiver) => {
1612:                 self.block_pending = Some(PendingBlockAction {
1613:                     receiver,
1614:                     sequence,
1615:                     position,
1616:                     expected_state: expected,
1617:                     place,
1618:                     deadline: (self.clock)() + Duration::from_secs(3),
1619:                     accepted: false,
1620:                 });
1621:             }
1622:             Err(error) if error.kind() == io::ErrorKind::Unsupported => {
1623:                 self.correct_block(writer, position)?;
1624:                 play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
1625:             }
1626:             Err(error) => return Err(error),
1627:         }
1628:         Ok(())
1629:     }
1631:     fn poll_block_action(&mut self, now: Instant, writer: &mut impl Write) -> io::Result<()> {
1632:         let Some(pending) = self.block_pending.as_mut() else {
1633:             return Ok(());
1634:         };
1635:         if now >= pending.deadline {
1636:             return self.disconnect_play(writer, "Block action confirmation timed out; reconnect");
1637:         }
1638:         if !pending.accepted {
1639:             match pending.receiver.try_recv() {
1640:                 Ok(Ok(())) => pending.accepted = true,
1641:                 Ok(Err(_)) => {
1642:                     let position = pending.position;
1643:                     let sequence = pending.sequence;
1644:                     self.block_pending = None;
1645:                     self.correct_block(writer, position)?;
1646:                     play::Clientbound::BlockAcknowledgement(sequence).write(writer)?;
1647:                     return Ok(());
1648:                 }
1649:                 Err(std::sync::mpsc::TryRecvError::Disconnected) => {
1650:                     return self
1651:                         .disconnect_play(writer, "Block action result unavailable; reconnect")
1652:                 }
1653:                 Err(std::sync::mpsc::TryRecvError::Empty) => return Ok(()),
1654:             }
1655:         }
1656:         let pending = self.block_pending.as_ref().unwrap();
1657:         let Some(session) = self.backend_session else {
1658:             return self.disconnect_play(writer, "Block action session missing; reconnect");
1659:         };
1660:         let Some(action) = self.backend.block_action_snapshot(session)? else {
1661:             return Ok(());
1662:         };
1663:         if action.sequence != self.block_sequence.saturating_add(1) {
1664:             return Ok(());
1665:         }
1666:         let position = pending.position;
1667:         let sequence = pending.sequence;
1668:         if (action.x, action.y, action.z) != (position.x, position.y, position.z)
1669:             || action.expected_state != pending.expected_state
1670:             || action.resulting_state != if pending.place { 1 } else { 0 }
1671:         {
1672:             return self.disconnect_play(writer, "Block action confirmation mismatch; reconnect");
1673:         }
1674:         self.block_pending = None;
1675:         self.block_sequence = action.sequence;
1676:         self.inventory_resync = true;
1677:         self.refresh_inventory(writer)?;
1678:         self.correct_block(writer, position)?;
1679:         play::Clientbound::BlockAcknowledgement(sequence).write(writer)
1680:     }
1682:     fn poll_chunk_overrides(&mut self, writer: &mut impl Write) -> io::Result<()> {
1683:         let Some(session) = self.backend_session else {
1684:             return Err(io::Error::new(
1685:                 io::ErrorKind::Unsupported,
1686:                 "Chunk snapshot requires backend session",
1687:             ));
1688:         };
1689:         for (chunk_x, chunk_z) in self.loaded_chunks.iter().copied().collect::<Vec<_>>() {
1690:             let snapshot = match self.backend.chunk_snapshot(session, chunk_x, chunk_z) {
1691:                 Ok(Some(snapshot)) => snapshot,
1692:                 Ok(None) if !self.backend.requires_persistent_world_snapshots() => continue,
1693:                 Err(error)
1694:                     if !self.backend.requires_persistent_world_snapshots()
1695:                         && error.kind() == io::ErrorKind::Unsupported =>
1696:                 {
1697:                     continue
1698:                 }
1699:                 Ok(None) => return Err(io::Error::other("Chunk snapshot view is unavailable")),
1700:                 Err(error) => return Err(error),
1701:             };
1702:             if self.chunk_revisions.get(&(chunk_x, chunk_z)) == Some(&snapshot.revision) {
1703:                 continue;
1704:             }
1705:             let overrides = decode_block_overrides(&snapshot, chunk_x, chunk_z)?;
1706:             for ((x, y, z), state) in &overrides {
1707:                 play::Clientbound::BlockUpdate(
1708:                     play::BlockPosition {
1709:                         x: *x,
1710:                         y: *y,
1711:                         z: *z,
1712:                     },
1713:                     *state,
1714:                 )
1715:                 .write(writer)?;
1716:             }
1717:             self.chunk_revisions
1718:                 .insert((chunk_x, chunk_z), snapshot.revision);
1719:         }
1720:         Ok(())
1721:     }
2130:     fn flush_chunk_interest(&mut self, now: Instant, writer: &mut impl Write) -> io::Result<()> {
2131:         if self.state != ConnectionState::Play || now < self.next_chunk_batch {
2132:             return Ok(());
2133:         }
2134:         let Some(center) = self.pending_chunk_center.take() else {
2135:             return Ok(());
2136:         };
2137:         let desired = chunk_window(center, self.chunk_radius);
2138:         let unload: Vec<_> = self.loaded_chunks.difference(&desired).copied().collect();
2139:         let load: Vec<_> = desired.difference(&self.loaded_chunks).copied().collect();
2140:         let world = rusty_mines::vanilla_world::world().map_err(invalid_data)?;
2141:         if center != self.chunk_center {
2142:             play::write_official_packet(
2143:                 writer,
2144:                 &play::chunk_center_at(&world.initialization[3], center.0, center.1)
2145:                     .map_err(invalid_data)?,
2146:             )?;
2147:         }
2148:         if self.chunk_radius != self.streamed_radius {
2149:             play::write_official_packet(
2150:                 writer,
2151:                 &play::chunk_distance(
2152:                     &world.initialization[4],
2153:                     play::RENDER_DISTANCE,
2154:                     self.chunk_radius,
2155:                 )
2156:                 .map_err(invalid_data)?,
2157:             )?;
2158:             play::write_official_packet(
2159:                 writer,
2160:                 &play::chunk_distance(
2161:                     &world.initialization[5],
2162:                     play::SIMULATION_DISTANCE,
2163:                     self.chunk_radius,
2164:                 )
2165:                 .map_err(invalid_data)?,
2166:             )?;
2167:         }
2168:         for (x, z) in unload {
2169:             play::write_official_packet(
2170:                 writer,
2171:                 &play::unload_chunk_at(&world.unload_template, x, z).map_err(invalid_data)?,
2172:             )?;
2173:         }
2174:         if !load.is_empty() {
2175:             play::write_official_packet(writer, &world.initialization[6])?;
2176:             let mut bytes = 0usize;
2177:             let mut loaded_chunks = Vec::new();
2178:             for (x, z) in &load {
2179:                 let chunk = play::chunk_at(&world.chunk_template, *x, *z).map_err(invalid_data)?;
2180:                 bytes = bytes
2181:                     .checked_add(chunk.len().saturating_add(5))
2182:                     .filter(|total| *total <= 2 * 1024 * 1024)
2183:                     .ok_or_else(|| invalid_data("chunk update exceeds byte budget"))?;
2184:                 play::write_official_packet(writer, &chunk)?;
2185:                 loaded_chunks.push((*x, *z));
2186:             }
2187:             let session = self
2188:                 .backend_session
2189:                 .ok_or_else(|| io::Error::other("Chunk load requires backend session"))?;
2190:             if !self.backend.requires_persistent_world_snapshots() {
2191:                 let finished = play::chunk_batch_finished(
2192:                     &world.initialization[world.initialization.len() - 2],
2193:                     load.len(),
2194:                 )
2195:                 .map_err(invalid_data)?;
2196:                 play::write_official_packet(writer, &finished)?;
2197:                 self.loaded_chunks = desired;
2198:                 self.chunk_revisions
2199:                     .retain(|key, _| self.loaded_chunks.contains(key));
2200:                 self.chunk_center = center;
2201:                 self.streamed_radius = self.chunk_radius;
2202:                 self.next_chunk_batch = now + SERVER_TICK;
2203:                 return Ok(());
2204:             }
2205:             if self.backend.requires_persistent_world_snapshots() {
2206:                 for (x, z) in &loaded_chunks {
2207:                     if let Some(snapshot) = self.backend.chunk_snapshot(session, *x, *z)? {
2208:                         decode_block_overrides(&snapshot, *x, *z)?;
2209:                     }
2210:                 }
2211:             }
2212:             let mut loaded_revisions = Vec::new();
2213:             for (x, z) in loaded_chunks {
2214:                 let Some(snapshot) = self.backend.chunk_snapshot(session, x, z)? else {
2215:                     if self.backend.requires_persistent_world_snapshots() {
2216:                         return Err(io::Error::other(
2217:                             "Chunk override snapshot is unavailable; refusing stale batch",
2218:                         ));
2219:                     }
2220:                     continue;
2221:                 };
2222:                 let overrides = decode_block_overrides(&snapshot, x, z)?;
2223:                 for ((block_x, block_y, block_z), state) in &overrides {
2224:                     play::Clientbound::BlockUpdate(
2225:                         play::BlockPosition {
2226:                             x: *block_x,
2227:                             y: *block_y,
2228:                             z: *block_z,
2229:                         },
2230:                         *state,
2231:                     )
2232:                     .write(writer)?;
2233:                 }
2234:                 loaded_revisions.push(((x, z), snapshot.revision));
2235:             }
2236:             let finished = play::chunk_batch_finished(
