2240:             .map_err(invalid_data)?;
2241:             play::write_official_packet(writer, &finished)?;
2242:             for (key, revision) in loaded_revisions {
2243:                 self.chunk_revisions.insert(key, revision);
2244:             }
2245:         }
2246:         self.loaded_chunks = desired;
2247:         self.chunk_revisions
2248:             .retain(|key, _| self.loaded_chunks.contains(key));
2249:         self.chunk_center = center;
2250:         self.streamed_radius = self.chunk_radius;
2251:         self.next_chunk_batch = now + SERVER_TICK;
2252:         Ok(())
2253:     }
