4311:         struct BlockBackend {
4312:             action: std::sync::Mutex<Option<crate::module_bindings::GatewayBlockAction>>,
4313:             state: std::sync::Mutex<i32>,
4314:             revision: std::sync::Mutex<u64>,
4315:             results: std::sync::Mutex<Vec<std::sync::mpsc::Sender<io::Result<()>>>>,
4316:             submits: std::sync::atomic::AtomicUsize,
4317:         }
4318:         impl BlockBackend {
4319:             fn new() -> Self {
4320:                 Self {
4321:                     action: std::sync::Mutex::new(None),
4322:                     state: std::sync::Mutex::new(1),
4323:                     revision: std::sync::Mutex::new(1),
4324:                     results: std::sync::Mutex::new(Vec::new()),
4325:                     submits: std::sync::atomic::AtomicUsize::new(0),
4326:                 }
4327:             }
