4329:             fn publish_action(&self, session_uuid: uuid::Uuid, state: i32, sequence: u64) {
4330:                 *self.state.lock().unwrap() = state;
4331:                 *self.revision.lock().unwrap() = sequence + 1;
4332:                 *self.action.lock().unwrap() = Some(crate::module_bindings::GatewayBlockAction {
4333:                     session_uuid: spacetimedb_sdk::Uuid::from_u128(session_uuid.as_u128()),
4334:                     sequence,
4335:                     x: 8,
4336:                     y: 63,
4337:                     z: 8,
4338:                     expected_state: 1,
4339:                     resulting_state: state as u32,
4340:                     revision: sequence + 1,
4341:                 });
4342:             }
4343:         }
4344:         impl SessionStore for BlockBackend {
4345:             fn begin(&self, _: uuid::Uuid, _: &str) -> io::Result<()> {
4346:                 Ok(())
4347:             }
4348:             fn configure(&self, _: uuid::Uuid) -> io::Result<i32> {
4349:                 Ok(16384)
4350:             }
4351:             fn play(&self, _: uuid::Uuid) -> io::Result<()> {
4352:                 Ok(())
