4378:             fn block_action_submit(
4379:                 &self,
4380:                 _: uuid::Uuid,
4381:                 _: u64,
4382:                 _: i32,
4383:                 _: i32,
4384:                 _: i32,
4385:                 _: u32,
4386:                 _: bool,
4387:             ) -> io::Result<std::sync::mpsc::Receiver<io::Result<()>>> {
4388:                 self.submits
4389:                     .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
